on conflict (key) do update set name = excluded.name, family = excluded.family, permission_status = excluded.permission_status,
  collection_mode = excluded.collection_mode, connector = excluded.connector, automated = excluded.automated, paid = excluded.paid,
  pipelines = excluded.pipelines, contact_route = excluded.contact_route, notes = excluded.notes, requirements = excluded.requirements,
  rate_limit = excluded.rate_limit, review_date = excluded.review_date,
  -- a permission downgrade switches automation off; operator choices are otherwise kept
